// ─── PWA Update Banner ────────────────────────────────────────────────────────
function useServiceWorkerUpdate() {
  const [showUpdate, setShowUpdate] = useState(false);
  const [waitingWorker, setWaitingWorker] = useState(null);
  useEffect(() => {
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker.ready.then((reg) => {
        reg.addEventListener("updatefound", () => {
          const newWorker = reg.installing;
          newWorker.addEventListener("statechange", () => {
            if (newWorker.state === "installed" && navigator.serviceWorker.controller) {
              setWaitingWorker(newWorker);
              setShowUpdate(true);
            }
          });
        });
      });
    }
  }, []);
  const applyUpdate = () => {
    if (waitingWorker) {
      waitingWorker.postMessage({ type: "SKIP_WAITING" });
      window.location.reload();
    }
  };
  return { showUpdate, applyUpdate };
}

// ─── Universal PDF Helper ─────────────────────────────────────────────────────
// Loads html2pdf.js from CDN on first use, then generates a real .pdf download.
const _loadHtml2Pdf = () => new Promise((resolve, reject) => {
  if (window.html2pdf) { resolve(window.html2pdf); return; }
  const s = document.createElement("script");
  s.src = "https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js";
  s.onload = () => resolve(window.html2pdf);
  s.onerror = reject;
  document.head.appendChild(s);
});

const downloadPDF = async (htmlContent, filename, session=null) => {
  const companyName = session?.companyName || null;
  const userName = session?.fullName || session?.name || null;
  // No TruckPilot branding — company header only
  const docHeader = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;padding:16px 20px;background:#1C2B4A;margin-bottom:0;border-radius:8px 8px 0 0;border-bottom:3px solid #E8962E;">
      <div>
        ${companyName ? `<div style="font-size:18px;font-weight:900;color:#fff;letter-spacing:0.5px;">${companyName}</div>` : ""}
        ${userName ? `<div style="font-size:12px;color:rgba(255,255,255,0.65);margin-top:3px;">${userName}</div>` : ""}
      </div>
      <div style="text-align:right;font-size:11px;color:rgba(255,255,255,0.5);margin-top:4px;">
        ${new Date().toLocaleDateString("en-CA",{year:"numeric",month:"long",day:"numeric"})}
      </div>
    </div>
    <div style="height:2px;background:linear-gradient(90deg,#E8962E,#FFD700);margin-bottom:24px;"></div>
  `;
  const fullHtml = `<div style="font-family:Arial,sans-serif;color:#1A1A1A;font-size:13px;line-height:1.5;">
<style>
  /* Kill any legacy brand/header/footer divs that may be inside report content */
  .brand,.footer,.header-brand,.report-logo{display:none!important}
  /* Amount columns always right-align */
  tfoot td{text-align:right!important;padding:10px!important;font-weight:900!important}
  tfoot td:first-child{text-align:left!important}
  td.right,th.right{text-align:right!important}
</style>
${docHeader}${htmlContent}
</div>`;

  try {
    const html2pdf = await _loadHtml2Pdf();
    const el = document.createElement("div");
    el.innerHTML = fullHtml;
    // Inject print styles inline so html2canvas renders them correctly
    el.querySelectorAll("table").forEach(t => { t.style.width="100%"; t.style.borderCollapse="collapse"; });
    document.body.appendChild(el);
    await html2pdf().set({
      margin: [12, 12, 12, 12],
      filename: filename + ".pdf",
      image: { type: "jpeg", quality: 0.97 },
      html2canvas: { scale: 2, useCORS: true, logging: false },
      jsPDF: { unit: "mm", format: "a4", orientation: "portrait" }
    }).from(el).save();
    document.body.removeChild(el);
    tpToast("PDF downloaded", "download", filename + ".pdf");
  } catch(err) {
    // Fallback: open in new window → browser print-to-PDF
    console.warn("html2pdf failed, falling back to print:", err);
    const styled = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${filename}</title>
<style>
  @page{margin:20mm} *{box-sizing:border-box}
  body{font-family:Arial,sans-serif;color:#1A1A1A;margin:0;padding:16px;font-size:13px;line-height:1.5}
  table{width:100%;border-collapse:collapse;margin:16px 0}
  th{background:#1C2B4A;padding:9px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:0.8px;color:#fff;font-weight:700}
  th.right{text-align:right}
  td{padding:9px 12px;border-bottom:1px solid #E8EEF4;font-size:13px;vertical-align:middle}
  td.right{text-align:right;font-weight:700}
  tfoot td{padding:10px 12px;font-weight:900;font-size:13px;background:#F5F8FF;border-top:2px solid #E8962E;text-align:right}
  tfoot td:first-child{text-align:left}
  .brand,.footer,.header,.header-brand,.report-logo{display:none!important}
  @media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style></head><body>${fullHtml}</body></html>`;
    const w = window.open("", "_blank");
    if (w) { w.document.write(styled); w.document.close(); w.focus(); w.print(); }
  }
};

