/* ── Ripple helper — call in onClick: tpRipple(e) ── */
const tpRipple = (e) => {
  try {
    const btn = e.currentTarget;
    const r = document.createElement("span");
    const rect = btn.getBoundingClientRect();
    const sz = Math.max(rect.width, rect.height);
    r.style.cssText = `width:${sz}px;height:${sz}px;left:${e.clientX - rect.left - sz / 2}px;top:${e.clientY - rect.top - sz / 2}px`;
    r.className = "tp-ripple";
    btn.appendChild(r);
    setTimeout(() => r.remove(), 700);
  } catch(err) {}
};

/* ── Global toast system ── */
let _tpToastEmit = null;
const tpToast = (msg, type="success", sub="") => { if (_tpToastEmit) _tpToastEmit({msg, type, sub}); };

function TPToastContainer() {
  const [toasts, setToasts] = useState([]);
  useEffect(() => {
    _tpToastEmit = (t) => {
      const id = Date.now();
      setToasts(prev => [...prev, { ...t, id }]);
      setTimeout(() => setToasts(prev => prev.map(x => x.id===id ? {...x, hiding:true} : x)), 2800);
      setTimeout(() => setToasts(prev => prev.filter(x => x.id !== id)), 3200);
    };
    return () => { _tpToastEmit = null; };
  }, []);

  if (!toasts.length) return null;
  const icons = { success:"✅", error:"⚠️", info:"ℹ️", download:"⬇" };
  const accents = { success:"#48c78e", error:"#EF4444", info:"#E8962E", download:"#1C2B4A" };
  return (
    <div style={{position:"fixed",bottom:100,left:"50%",transform:"translateX(-50%)",zIndex:99999,display:"flex",flexDirection:"column",gap:8,alignItems:"center",pointerEvents:"none",width:"calc(100% - 32px)",maxWidth:380}}>
      {toasts.map(t => (
        <div key={t.id} className={`tp-toast${t.hiding?" tp-toast-out":""}`}
          style={{background:"#1C2B4A",color:"#fff",padding:"13px 17px",borderRadius:14,display:"flex",alignItems:"center",gap:11,boxShadow:"0 8px 32px rgba(0,0,0,.35)",borderLeft:`4px solid ${accents[t.type]||accents.info}`,fontSize:13,fontWeight:600,width:"100%"}}>
          <span style={{fontSize:19}}>{icons[t.type]||icons.info}</span>
          <div>
            <div style={{fontWeight:700,marginBottom:t.sub?2:0}}>{t.msg}</div>
            {t.sub && <div style={{fontSize:11,opacity:.6}}>{t.sub}</div>}
          </div>
        </div>
      ))}
    </div>
  );
}
const fmt = (m) => { const h = Math.floor(m / 60), mn = m % 60; return `${h}h ${mn}m`; };
const secsToHMS = (s) => { const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60; return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(ss).padStart(2,"0")}`; };

